css:
.lxdesignsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #2a2440;
    background: linear-gradient(160deg, #f4f1fb 0%, #ece7f7 100%);
    border-radius: 18px;
}

.lxdesignsim-container * {
    box-sizing: border-box;
}

.lxdesignsim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #4326a0 0%, #6a3fc0 55%, #9a5fd6 100%);
    color: #f7f4ff;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 10px 30px rgba(67, 38, 160, 0.30);
}

.lxdesignsim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
}

.lxdesignsim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #e7d9ff;
    background: rgba(255, 255, 255, 0.14);
    padding: 5px 14px;
    border-radius: 999px;
}

.lxdesignsim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #eee6ff;
}

.lxdesignsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #4a3a7a;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.lxdesignsim-period-counter #currentDay,
.lxdesignsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #4326a0;
}

.lxdesignsim-round-name {
    background: #e3d8f7;
    color: #4326a0;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.lxdesignsim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #a8511b;
    background: #fdeede;
    padding: 4px 12px;
    border-radius: 999px;
}

.lxdesignsim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.lxdesignsim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #e1d8f2;
    box-shadow: 0 4px 14px rgba(67, 38, 160, 0.06);
    border-top: 4px solid #6a3fc0;
}

.lxdesignsim-card-completion { border-top-color: #2f9e6f; }
.lxdesignsim-card-outcome { border-top-color: #c08a16; }
.lxdesignsim-card-engagement { border-top-color: #6a3fc0; }
.lxdesignsim-card-budget { border-top-color: #2f6fb0; }

.lxdesignsim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #7a6ca0;
}

.lxdesignsim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #4326a0;
}

.lxdesignsim-card-completion .lxdesignsim-value { color: #2f9e6f; }
.lxdesignsim-card-outcome .lxdesignsim-value { color: #c08a16; }
.lxdesignsim-card-engagement .lxdesignsim-value { color: #6a3fc0; }
.lxdesignsim-card-budget .lxdesignsim-value { color: #2f6fb0; }

.lxdesignsim-sublabel {
    font-size: 0.76rem;
    color: #8377a6;
    line-height: 1.35;
}

.lxdesignsim-completion-fail .lxdesignsim-value { color: #c0392b; }
.lxdesignsim-completion-target .lxdesignsim-value { color: #2f9e6f; }

.lxdesignsim-budget-over { border-top-color: #c0392b; }
.lxdesignsim-budget-over .lxdesignsim-value { color: #c0392b; }

.lxdesignsim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #4326a0;
    color: #f1ebff;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.lxdesignsim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
}

.lxdesignsim-budget-bar.lxdesignsim-bar-over {
    background: #8a1f1f;
}

.lxdesignsim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #6a3fc0;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(67, 38, 160, 0.05);
}

.lxdesignsim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.lxdesignsim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #4326a0;
    margin-bottom: 6px;
}

.lxdesignsim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #3b3358;
}

.lxdesignsim-briefing-text strong { color: #2f9e6f; }
.lxdesignsim-briefing-text em { color: #a8511b; font-style: italic; }

.lxdesignsim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #e1d8f2;
    box-shadow: 0 4px 14px rgba(67, 38, 160, 0.06);
}

.lxdesignsim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #4326a0;
    border-bottom: 2px solid #ede7f8;
    padding-bottom: 8px;
}

.lxdesignsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #382f5c;
    margin: 14px 0 6px;
}

.lxdesignsim-container select,
.lxdesignsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #cfc1ec;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #faf8ff;
    color: #2a2440;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.lxdesignsim-container select:focus,
.lxdesignsim-container input[type="number"]:focus {
    outline: none;
    border-color: #6a3fc0;
    box-shadow: 0 0 0 3px rgba(106, 63, 192, 0.15);
}

.lxdesignsim-container select option {
    background-color: #ffffff;
    color: #2a2440;
}

.lxdesignsim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #6a3fc0;
}

.lxdesignsim-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #5a3fa0;
    margin-top: 4px;
}

.lxdesignsim-range-readout span:last-child {
    color: #2f9e6f;
    font-weight: 800;
}

.lxdesignsim-hint {
    font-size: 0.8rem;
    color: #8377a6;
    margin-top: 4px;
    line-height: 1.4;
}

.lxdesignsim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.lxdesignsim-container .btn-primary {
    background: linear-gradient(135deg, #4326a0 0%, #8a5fd6 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 6px 16px rgba(67, 38, 160, 0.28);
}

.lxdesignsim-container .btn-primary:hover {
    filter: brightness(1.08);
}

.lxdesignsim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #cfc1ec;
    color: #7a6ca0;
}

.lxdesignsim-coach {
    background: #2a1d52;
    color: #efe9ff;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(42, 29, 82, 0.28);
}

.lxdesignsim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #b89bf0;
    margin-bottom: 8px;
}

.lxdesignsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.lxdesignsim-coach-body strong { color: #ffd98a; }
.lxdesignsim-coach-body em { color: #ffc1ad; font-style: italic; }

.lxdesignsim-history,
.lxdesignsim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #e1d8f2;
    box-shadow: 0 4px 14px rgba(67, 38, 160, 0.06);
}

.lxdesignsim-history h3,
.lxdesignsim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #4326a0;
}

.lxdesignsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #382f5c;
}

.lxdesignsim-container table#usfHistoryTable th {
    background: #f0eafa;
    color: #4326a0;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #ddd0f2;
}

.lxdesignsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #f1ecf9;
}

.lxdesignsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #faf8ff;
}

.lxdesignsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .lxdesignsim-container {
        padding: 14px;
    }
    .lxdesignsim-header h1 {
        font-size: 1.7rem;
    }
    .lxdesignsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .lxdesignsim-value {
        font-size: 2rem;
    }
    .lxdesignsim-clock {
        margin-left: 0;
    }
    .lxdesignsim-period-counter {
        font-size: 0.88rem;
    }
    .lxdesignsim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .lxdesignsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ---- v1.1.0 completion / debrief screen (light theme) ---- */
.lxdesignsim-completion { padding: 8px 4px 4px; }
.lxdesignsim-cm-head { text-align: center; margin-bottom: 16px; }
.lxdesignsim-cm-score { font-size: 3.2rem; font-weight: 800; line-height: 1; color: #4326a0; }
.lxdesignsim-cm-score-max { font-size: 1.2rem; font-weight: 600; color: #6a3fc0; }
.lxdesignsim-cm-grade { font-size: 1.2rem; font-weight: 700; margin-top: 6px; color: #2a2440; }
.lxdesignsim-cm-badge { display: inline-block; margin-left: 6px; padding: 2px 10px; border-radius: 999px; font-size: 0.78rem; font-weight: 700; vertical-align: middle; }
.lxdesignsim-cm-yes { background: rgba(47,158,111,0.14); color: #1f7d55; border: 1px solid rgba(47,158,111,0.5); }
.lxdesignsim-cm-no { background: rgba(192,57,43,0.12); color: #b23325; border: 1px solid rgba(192,57,43,0.45); }
.lxdesignsim-cm-metrics { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin: 12px 0 16px; }
.lxdesignsim-cm-metric { flex: 1 1 120px; min-width: 108px; background: rgba(106,63,192,0.07); border: 1px solid rgba(106,63,192,0.22); border-radius: 10px; padding: 10px 8px; text-align: center; }
.lxdesignsim-cm-mv { display: block; font-size: 1.4rem; font-weight: 800; color: #4326a0; }
.lxdesignsim-cm-ml { display: block; font-size: 0.72rem; margin-top: 4px; color: #6b6480; text-transform: uppercase; letter-spacing: 0.03em; }
.lxdesignsim-cm-insights-title { font-weight: 700; margin: 8px 0 6px; color: #2a2440; }
.lxdesignsim-cm-insights { margin: 0; padding-left: 20px; }
.lxdesignsim-cm-insights li { margin-bottom: 8px; line-height: 1.5; font-size: 0.92rem; color: #3a3452; }

