(function() {
    'use strict';

    class JourneyAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Designing the Learning Journey`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (money in EUR thousands).
            this.START_COMPLETION = 61;     // existing-certificate median
            this.TARGET_COMPLETION = 85;    // board target
            this.FAIL_COMPLETION = 70;      // pilot failure threshold
            this.ASYNC_FLOOR = 48;          // fully self-paced historical completion
            this.START_OUTCOME = 2.5;       // attainment out of 5
            this.START_ENGAGEMENT = 42;     // 0-100 (leaves headroom so meters don't peg before R4)
            this.BUDGET_CAP = 540;          // EUR 540k design-and-production budget
            this.COHORT = 120;              // target seats

            // Format costs (EUR k).
            this.RESIDENTIAL_FIXED = 95;    // per two-day residential
            this.RESIDENTIAL_TRAVEL = 132;  // EUR 1.1k * 120 learners, per residential
            this.SYNC_EACH = 6;             // per live online cohort session
            this.FORMATIVE_EACH = 1.8;      // per formative check
            this.CAPSTONE = 22;             // sponsor-visible capstone

            // Concept truths.
            this.TRUE_ROOT = `design`;
            this.TRUE_LEVER = `drivers`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    completion: this.START_COMPLETION,
                    outcome: this.START_OUTCOME,
                    engagement: this.START_ENGAGEMENT,
                    budgetUsed: 0,
                    cpl: 0,
                    overBudget: false,
                    completionTunnel: false,
                    completionHistory: [this.START_COMPLETION],
                    outcomeHistory: [Math.round(this.START_OUTCOME * 20)],
                    engagementHistory: [this.START_ENGAGEMENT],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    root: `design`,
                    lever: `drivers`,
                    focus: 60,
                    residential: `one`,
                    sync: 5,
                    async: `balanced`,
                    social: 55,
                    formative: 5,
                    placement: `cliff`,
                    capstone: `capstone_formative`,
                    evidence: 60,
                    diagnosis: `designmiss`,
                    realloc: `curve`,
                    outcomeStrat: `joint`,
                    pitch: 70
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const root = document.getElementById(`rootInput`);
                const lever = document.getElementById(`leverInput`);
                const focus = document.getElementById(`focusInput`);
                if (root) decisions.root = root.value;
                if (lever) decisions.lever = lever.value;
                if (focus) decisions.focus = parseInt(focus.value, 10);
                if (!Number.isFinite(decisions.focus) || decisions.focus < 0 || decisions.focus > 100) {
                    warn(`warn_focus_range`); return false;
                }
            } else if (round === 2) {
                const res = document.getElementById(`residentialInput`);
                const sync = document.getElementById(`syncInput`);
                const asy = document.getElementById(`asyncInput`);
                const soc = document.getElementById(`socialInput`);
                if (res) decisions.residential = res.value;
                if (asy) decisions.async = asy.value;
                if (sync) decisions.sync = parseInt(sync.value, 10);
                if (soc) decisions.social = parseFloat(soc.value);
                if (!Number.isFinite(decisions.sync) || decisions.sync < 0 || decisions.sync > 10) {
                    warn(`warn_sync_range`); return false;
                }
                if (!Number.isFinite(decisions.social) || decisions.social < 0 || decisions.social > 120) {
                    warn(`warn_social_range`); return false;
                }
            } else if (round === 3) {
                const fm = document.getElementById(`formativeInput`);
                const pl = document.getElementById(`placementInput`);
                const cap = document.getElementById(`capstoneInput`);
                const ev = document.getElementById(`evidenceInput`);
                if (pl) decisions.placement = pl.value;
                if (cap) decisions.capstone = cap.value;
                if (fm) decisions.formative = parseInt(fm.value, 10);
                if (ev) decisions.evidence = parseInt(ev.value, 10);
                if (!Number.isFinite(decisions.formative) || decisions.formative < 0 || decisions.formative > 12) {
                    warn(`warn_formative_range`); return false;
                }
                if (!Number.isFinite(decisions.evidence) || decisions.evidence < 0 || decisions.evidence > 100) {
                    warn(`warn_evidence_range`); return false;
                }
            } else if (round === 4) {
                const di = document.getElementById(`diagnosisInput`);
                const re = document.getElementById(`reallocInput`);
                const os = document.getElementById(`outcomeStratInput`);
                const pi = document.getElementById(`pitchInput`);
                if (di) decisions.diagnosis = di.value;
                if (re) decisions.realloc = re.value;
                if (os) decisions.outcomeStrat = os.value;
                if (pi) decisions.pitch = parseInt(pi.value, 10);
                if (!Number.isFinite(decisions.pitch) || decisions.pitch < 0 || decisions.pitch > 100) {
                    warn(`warn_pitch_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            // engagementDelta = drivers of completion; outcomeDelta = real learning (0-5 scale);
            // hollowDelta = completion bought WITHOUT learning (tunnel vision); spend = EUR k this round.
            let engagementDelta = 0, outcomeDelta = 0, hollowDelta = 0, spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose the design problem, not content / production / the learners (Common Error framing).
                if (d.root === this.TRUE_ROOT) {
                    engagementDelta += 12; outcomeDelta += 0.20; coachKey = `coach_r1_root_right`;
                } else if (d.root === `production`) {
                    engagementDelta -= 8; coachKey = `coach_r1_production`;
                } else if (d.root === `content`) {
                    engagementDelta -= 4; outcomeDelta -= 0.05; coachKey = `coach_r1_content`;
                } else {
                    engagementDelta -= 10; coachKey = `coach_r1_learners`;
                }

                // Distinguish engagement drivers from engagement theatre.
                if (d.lever === this.TRUE_LEVER) {
                    engagementDelta += 12; outcomeDelta += 0.15;
                    if (d.root === this.TRUE_ROOT) coachKey = `coach_r1_diag_sharp`;
                } else if (d.lever === `gloss`) {
                    engagementDelta -= 6; coachKey = `coach_r1_gloss`;
                } else if (d.lever === `extras`) {
                    engagementDelta -= 2;
                } else {
                    engagementDelta -= 8; coachKey = `coach_r1_levernone`;
                }

                // Concentrating the diagnosis on the diagnosed cliff sets up Round 3 targeting.
                if (d.focus >= 60) { engagementDelta += 6; }
                else if (d.focus <= 25) { engagementDelta -= 6; coachKey = `coach_r1_lowfocus`; }

                summaryKey = (d.root === this.TRUE_ROOT && d.lever === this.TRUE_LEVER) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Choose the blend within EUR 540k (Common Errors: wish-list & cheapest-blend).
                // Residential cost includes per-learner travel — two residentials nearly eat the whole budget.
                const resCount = d.residential === `two` ? 2 : (d.residential === `none` ? 0 : 1);
                spend += resCount * (this.RESIDENTIAL_FIXED + this.RESIDENTIAL_TRAVEL);
                if (resCount === 1) { engagementDelta += 12; outcomeDelta += 0.25; coachKey = `coach_r2_resone`; }
                else if (resCount === 2) { engagementDelta += 16; outcomeDelta += 0.30; coachKey = `coach_r2_restwo`; }
                else { engagementDelta -= 4; coachKey = `coach_r2_resnone`; }

                // Live online synchronous touchpoints — momentum & relatedness.
                spend += d.sync * this.SYNC_EACH;
                if (d.sync >= 4 && d.sync <= 8) { engagementDelta += 10; outcomeDelta += 0.15; }
                else if (d.sync >= 1) { engagementDelta += 4; }
                else { engagementDelta -= 6; }

                // Async backbone. A balanced backbone supports the live blend; fully-async is the
                // cheapest-blend fallacy (caps completion near the 48% async floor).
                let asyncFloorPull = false;
                switch (d.async) {
                    case `balanced`: spend += 120; engagementDelta += 6; outcomeDelta += 0.15; break;
                    case `full`: spend += 90; engagementDelta -= 14; outcomeDelta -= 0.10; asyncFloorPull = true; coachKey = `coach_r2_async`; break;
                    case `thin`: spend += 60; engagementDelta -= 2; outcomeDelta -= 0.05; break;
                }

                // Social-accountability layer (peer circles, milestones, light AI tutor) — high engagement per euro.
                spend += d.social;
                if (d.social >= 45) { engagementDelta += 12; outcomeDelta += 0.10; if (coachKey === `coach_default`) coachKey = `coach_r2_social`; }
                else if (d.social >= 20) { engagementDelta += 5; }
                else { engagementDelta -= 6; if (coachKey === `coach_default`) coachKey = `coach_r2_nosocial`; }

                // Cheapest-blend fallacy: full async with little social = completion pulled toward 48%.
                if (asyncFloorPull && d.social < 45) { engagementDelta -= 6; coachKey = `coach_r2_cheapblend`; }

                summaryKey = (resCount >= 1 && d.async !== `full` && d.social >= 45) ? `sum_r2_good`
                    : (d.async === `full` ? `sum_r2_cheap` : `sum_r2_weak`);
            } else if (round === 3) {
                // Sequence assessment & engineer momentum (Common Errors: terminal-only & uniform).
                spend += d.formative * this.FORMATIVE_EACH;

                // Formative volume — feedback-rich early-warning.
                if (d.formative >= 4 && d.formative <= 8) { engagementDelta += 8; outcomeDelta += 0.20; }
                else if (d.formative >= 1) { engagementDelta += 3; outcomeDelta += 0.05; }
                else { engagementDelta -= 8; outcomeDelta -= 0.10; coachKey = `coach_r3_noformative`; }

                // Placement — design follows the curve, not the calendar.
                switch (d.placement) {
                    case `cliff`: engagementDelta += 12; coachKey = `coach_r3_cliff`; break;
                    case `even`: engagementDelta -= 4; coachKey = `coach_r3_even`; break;
                    case `late`: engagementDelta -= 8; coachKey = `coach_r3_late`; break;
                }

                // Capstone vs single final (assessment rhythm + outcome evidence).
                switch (d.capstone) {
                    case `capstone_formative`: spend += this.CAPSTONE; outcomeDelta += 0.30; engagementDelta += 4; if (d.placement === `cliff`) coachKey = `coach_r3_architecture`; break;
                    case `finalonly`: spend += this.CAPSTONE; outcomeDelta -= 0.15; engagementDelta -= 6; coachKey = `coach_r3_finalonly`; break;
                    case `nocapstone`: outcomeDelta -= 0.10; coachKey = `coach_r3_nocapstone`; break;
                }

                // Backward-design outcome-evidence trail for EQUIS.
                if (d.evidence >= 60) { outcomeDelta += 0.30; }
                else if (d.evidence <= 25) { outcomeDelta -= 0.20; coachKey = `coach_r3_noevidence`; }

                summaryKey = (d.placement === `cliff` && d.capstone === `capstone_formative` && d.formative >= 4) ? `sum_r3_good`
                    : (d.capstone === `finalonly` ? `sum_r3_terminal` : `sum_r3_weak`);
            } else if (round === 4) {
                // Pilot results & iterate (Common Errors: bad-luck rationalisation & completion tunnel vision).
                switch (d.diagnosis) {
                    case `designmiss`: engagementDelta += 8; outcomeDelta += 0.10; coachKey = `coach_r4_designmiss`; break;
                    case `badluck`: engagementDelta -= 8; coachKey = `coach_r4_badluck`; break;
                    case `learners`: engagementDelta -= 10; coachKey = `coach_r4_learners`; break;
                }

                // Reallocate v2 toward the diagnosed risk.
                switch (d.realloc) {
                    case `curve`: engagementDelta += 12; outcomeDelta += 0.15; coachKey = (d.diagnosis === `designmiss`) ? `coach_r4_curve` : coachKey; break;
                    case `residential`: spend += this.RESIDENTIAL_FIXED + this.RESIDENTIAL_TRAVEL; engagementDelta += 4; coachKey = `coach_r4_residential`; break;
                    case `flat`: engagementDelta -= 6; coachKey = `coach_r4_flat`; break;
                }

                // Joint optimisation of engagement AND outcomes (the central LO).
                switch (d.outcomeStrat) {
                    case `joint`: engagementDelta += 8; outcomeDelta += 0.40; if (d.realloc === `curve`) coachKey = `coach_r4_joint`; break;
                    case `completion`: engagementDelta += 6; outcomeDelta -= 0.80; hollowDelta += 8; coachKey = `coach_r4_completion`; break;
                    case `rigour`: engagementDelta -= 8; outcomeDelta += 0.25; coachKey = `coach_r4_rigour`; break;
                }

                // Conviction nudges outcome ownership.
                outcomeDelta += (d.pitch - 60) / 200;

                summaryKey = (d.diagnosis === `designmiss` && d.realloc === `curve` && d.outcomeStrat === `joint`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Resource accounting.
            ds.budgetUsed = Math.round((ds.budgetUsed + spend) * 10) / 10;
            ds.cpl = Math.round((ds.budgetUsed * 1000) / this.COHORT);
            if (ds.budgetUsed > this.BUDGET_CAP + 0.001) ds.overBudget = true;

            // Over-budget designs destroy the contribution margin — engagement gains are clawed back
            // because the programme would have to be re-scoped or run at a loss (wish-list penalty).
            if (ds.overBudget) {
                const overBy = ds.budgetUsed - this.BUDGET_CAP;
                const penalty = Math.min(18, 6 + overBy / 12);
                engagementDelta -= penalty;
                outcomeDelta -= 0.10;
                if (round === 2) coachKey = `coach_r2_overbudget`;
            }

            // Engagement quality moves on its delta (0-100). The delta is damped so a strong
            // four-round design lands high-but-unpegged — every round's lever (including the
            // R3 placement and R4 levers) leaves a visible trace instead of saturating at 100.
            const ENG_SCALE = 0.46;
            ds.engagement = Math.max(0, Math.min(100, ds.engagement + engagementDelta * ENG_SCALE));
            // Outcome attainment moves on its delta (0-5), damped so a correct run lands ~4.1
            // rather than pegging at 5.0 — which is what lets the tunnel-vision lever (chase
            // completion, sacrifice learning) actually pull attainment below the 3.4 learning line.
            const OUT_SCALE = 0.62;
            ds.outcome = Math.max(0, Math.min(5, Math.round((ds.outcome + outcomeDelta * OUT_SCALE) * 100) / 100));

            // Completion is driven by genuine engagement PLUS any hollow/tunnel-vision gains.
            // Hollow gains lift the headline completion but not real learning (outcome).
            const engGain = engagementDelta * ENG_SCALE * 0.45;
            const hollowGain = hollowDelta * 0.7;
            let completionDelta = engGain + hollowGain;
            ds.completion = Math.max(0, Math.min(97, ds.completion + completionDelta));

            // Fully-async cheapest-blend fallacy pins completion toward the 48% historical floor.
            if (round === 2 && d.async === `full` && d.social < 45 && ds.completion > this.ASYNC_FLOOR + 8) {
                ds.completion = this.ASYNC_FLOOR + 8;
            }

            // Completion tunnel vision: people finish but do not learn. The learning line sits at
            // 3.4 (just under the 3.5 "real learning" bar) so a high-completion design that chases
            // completion at the expense of outcomes is flagged rather than slipping through.
            if (hollowDelta >= 6 && ds.outcome < 3.4 && ds.completion >= this.TARGET_COMPLETION) ds.completionTunnel = true;

            ds.completionHistory.push(Math.round(ds.completion));
            ds.outcomeHistory.push(Math.round(ds.outcome * 20));
            ds.engagementHistory.push(Math.round(ds.engagement));

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // Expose composite (0-100) to the reporting/grading layer every period
            // (express/results_utils.php::express_resolveDomainScore reads domainState.performance.overallScore).
            ds.performance = { overallScore: this._composite(ds) };

            return {
                period: state.currentPeriod,
                completion: Math.round(ds.completion),
                completionDelta: Math.round(completionDelta),
                outcome: ds.outcome,
                outcomeDelta: Math.round(outcomeDelta * 100) / 100,
                engagement: Math.round(ds.engagement),
                engagementDelta: Math.round(engagementDelta),
                budgetUsed: ds.budgetUsed,
                cpl: ds.cpl,
                overBudget: ds.overBudget,
                completionTunnel: ds.completionTunnel,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);
            uiManager.bind(`completionDisplay`, `domainState.completion`, (v) => {
                const card = document.querySelector(`.lxdesignsim-card-completion`);
                if (card) {
                    card.classList.toggle(`lxdesignsim-completion-target`, Number(v) >= this.TARGET_COMPLETION);
                    card.classList.toggle(`lxdesignsim-completion-fail`, Number(v) < this.FAIL_COMPLETION);
                }
                return Math.round(Number(v)) + `%`;
            });
            uiManager.bind(`outcomeDisplay`, `domainState.outcome`, (v) => Number(v).toFixed(1));
            uiManager.bind(`engagementDisplay`, `domainState.engagement`, (v) => Math.round(Number(v)));
            uiManager.bind(`cplDisplay`, `domainState.cpl`, (v) => this._money(Number(v)));
            uiManager.bind(`budgetDisplay`, `domainState.budgetUsed`, (v) => {
                const bar = document.querySelector(`.lxdesignsim-budget-bar`);
                if (bar) bar.classList.toggle(`lxdesignsim-bar-over`, Number(v) > this.BUDGET_CAP + 0.001);
                const card = document.querySelector(`.lxdesignsim-card-budget`);
                if (card) card.classList.toggle(`lxdesignsim-budget-over`, Number(v) > this.BUDGET_CAP + 0.001);
                return `€` + (Math.round(Number(v) * 10) / 10) + `k / €540k`;
