            const focus = document.getElementById(`focusInput`);
            const focusReadout = document.getElementById(`focusReadout`);
            if (focus && focusReadout) {
                focusReadout.textContent = focus.value;
                focus.addEventListener(`input`, function() { focusReadout.textContent = focus.value; });
            }

            // Evidence slider readout.
            const ev = document.getElementById(`evidenceInput`);
            const evReadout = document.getElementById(`evidenceReadout`);
            if (ev && evReadout) {
                evReadout.textContent = ev.value;
                ev.addEventListener(`input`, function() { evReadout.textContent = ev.value; });
            }
        }

        // EUR formatter: symbol after the number in Spanish, before in English.
        _money(value) {
            const lang = (window.mySimulation && window.mySimulation.language) || `en`;
            const n = Math.round(Number(value) || 0);
            return lang === `es` ? (n.toLocaleString(`es-ES`) + ` €`) : (`€` + n.toLocaleString(`en-US`));
        }

        getChartConfig() {
