        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.completionHistory.map((_, i) => (i === 0 ? `Start` : `R` + i));
            return {
                journeyChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.completionHistory },
                        { data: ds.outcomeHistory },
                        { data: ds.engagementHistory }
                    ]
                }
            };
        }

        // Composite (0-100) written to domainState.performance.overallScore each period for the
        // reporting/grading layer. Formula copied VERBATIM from v1.0.0 getPerformanceSummary.
        _composite(ds) {
            const completion = Math.round(ds.completion);
            const outcome = Math.round(ds.outcome * 10) / 10;
            const engagement = Math.round(ds.engagement);
            const composite = Math.round(Math.min(100, completion) * 0.40 + (outcome * 20) * 0.35 + engagement * 0.25);
            return Math.max(0, Math.min(100, composite));
        }

        _cl(key, fallback) {
            try {
                const v = (window.mySimulation && typeof window.mySimulation.t === `function`)
                    ? window.mySimulation.t(key) : key;
                return (v && v !== key) ? v : fallback;
            } catch (e) { return fallback; }
        }

        formatCompletionMessage(summary) {
            const T = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? function(k) { return window.mySimulation.t(k); }
                : function(k) { return k; };
            const s = summary || {};
            const score = (typeof s.totalScore === `number`) ? s.totalScore
                : (typeof s.overallScore === `number` ? s.overallScore
                : (typeof s.composite === `number` ? s.composite : 0));
            const grade = s.performance || (s.performanceKey ? T(s.performanceKey) : ``);
            const met = !!(s.hitTarget && s.realLearning && s.onBudget);
            const badge = met
                ? `<span class="lxdesignsim-cm-badge lxdesignsim-cm-yes">` + T(`cm_won`) + `</span>`
                : `<span class="lxdesignsim-cm-badge lxdesignsim-cm-no">` + T(`cm_notwon`) + `</span>`;
            const riskBadge = (s.onBudget === false)
                ? ` <span class="lxdesignsim-cm-badge lxdesignsim-cm-no">` + T(`cm_overbudget`) + `</span>`
                : ``;
            const insights = Array.isArray(s.insights) ? s.insights : [];
            const items = insights.map(function(t) { return `<li>` + t + `</li>`; }).join(``);
            const outStr = (typeof s.outcome === `number`) ? s.outcome.toFixed(1) : String(s.outcome || ``);
            const cplStr = (s.cpl != null) ? String(s.cpl) : ``;
            const metrics = ``
                + `<div class="lxdesignsim-cm-metric"><span class="lxdesignsim-cm-mv">` + Math.round(s.completion || 0) + `%</span><span class="lxdesignsim-cm-ml">` + T(`cm_m_completion`) + `</span></div>`
                + `<div class="lxdesignsim-cm-metric"><span class="lxdesignsim-cm-mv">` + outStr + `</span><span class="lxdesignsim-cm-ml">` + T(`cm_m_outcome`) + `</span></div>`
                + `<div class="lxdesignsim-cm-metric"><span class="lxdesignsim-cm-mv">` + Math.round(s.engagement || 0) + `</span><span class="lxdesignsim-cm-ml">` + T(`cm_m_engagement`) + `</span></div>`
                + `<div class="lxdesignsim-cm-metric"><span class="lxdesignsim-cm-mv">` + cplStr + `</span><span class="lxdesignsim-cm-ml">` + T(`cm_m_cpl`) + `</span></div>`;
            return ``
                + `<div class="lxdesignsim-completion">`
                +   `<div class="lxdesignsim-cm-head">`
                +     `<div class="lxdesignsim-cm-score">` + score + `<span class="lxdesignsim-cm-score-max">/100</span></div>`
                +     `<div class="lxdesignsim-cm-grade">` + grade + ` ` + badge + riskBadge + `</div>`
                +   `</div>`
                +   `<div class="lxdesignsim-cm-metrics">` + metrics + `</div>`
                +   `<div class="lxdesignsim-cm-insights-title">` + T(`cm_debrief`) + `</div>`
                +   `<ul class="lxdesignsim-cm-insights">` + items + `</ul>`
                + `</div>`;
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const completion = Math.round(ds.completion);
            const outcome = Math.round(ds.outcome * 10) / 10;
            const engagement = Math.round(ds.engagement);

            const hitTarget = completion >= this.TARGET_COMPLETION;
            const passedPilot = completion >= this.FAIL_COMPLETION;
            const realLearning = outcome >= 3.5;
            const tunnel = ds.completionTunnel || (hitTarget && outcome < 3.4);
            const onBudget = !ds.overBudget;
            const composite = Math.round(Math.min(100, completion) * 0.40 + (outcome * 20) * 0.35 + engagement * 0.25);

            let performanceKey = `grade_relapse`;
            if (hitTarget && realLearning && onBudget && composite >= 78) performanceKey = `grade_flagship`;
            else if (hitTarget && realLearning && onBudget) performanceKey = `grade_blueprint`;
            else if (hitTarget && tunnel) performanceKey = `grade_tunnel`;
            else if (hitTarget && !onBudget) performanceKey = `grade_lossmaking`;
            else if (hitTarget) performanceKey = `grade_thin`;
            else if (passedPilot) performanceKey = `grade_pilot`;
            else if (completion > this.START_COMPLETION + 8) performanceKey = `grade_improving`;
            const performance = window.mySimulation.t(performanceKey);

            const insights = [];
            if (hitTarget && realLearning && onBudget) insights.push(window.mySimulation.t(`insight_flagship`));
            else if (hitTarget && tunnel) insights.push(window.mySimulation.t(`insight_tunnel`));
            else if (hitTarget && !onBudget) insights.push(window.mySimulation.t(`insight_overbudget`));
            else if (hitTarget) insights.push(window.mySimulation.t(`insight_thin`));
            else if (!passedPilot) insights.push(window.mySimulation.t(`insight_pilotfail`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (ds.overBudget) insights.push(window.mySimulation.t(`insight_margin`));
            if (outcome < 3.0) insights.push(window.mySimulation.t(`insight_lowoutcome`));
            if (engagement < 45) insights.push(window.mySimulation.t(`insight_lowengagement`));
            if (hitTarget && realLearning && onBudget && composite >= 78) insights.push(window.mySimulation.t(`insight_joint`));

            return {
                completion: completion,
                outcome: outcome,
                engagement: engagement,
                cpl: ds.cpl,
                budgetUsed: ds.budgetUsed,
                hitTarget: hitTarget,
                tunnel: tunnel,
                onBudget: onBudget,
                realLearning: realLearning,
                composite: composite,
                totalScore: composite,
                overallScore: composite,
                performanceKey: performanceKey,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.overBudget) return window.mySimulation.t(`hint_overbudget`);
            if (ds.completionTunnel) return window.mySimulation.t(`hint_tunnel`);
            if (ds.outcome < 2.5 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_outcome`);
            if (state.currentPeriod >= 2 && ds.completion <= this.ASYNC_FLOOR + 10) return window.mySimulation.t(`hint_async`);
            if (state.currentPeriod >= 3 && ds.completion < 75) return window.mySimulation.t(`hint_behind`);
            if (ds.completion >= this.TARGET_COMPLETION && ds.outcome >= 3.5 && !ds.overBudget) return window.mySimulation.t(`hint_strong`);
            return null;
        }

